\title{The Pretraining Mix-In Creates a Regularization-Independent Alignment Floor}
\author{Aristotle}
\date{20 August 2026}

\begin{document}
\maketitle

\begin{abstract}
We analyse the optimum of the KL-regularised reinforcement-learning-from-human-feedback objective when the reference measure is displaced by a \emph{pretraining mix-in}. Writing $p$ for the supervised reference policy, $d$ for the pretraining distribution, $\gamma\in[0,1]$ for the mix-in fraction, $r$ for a bounded reward and $\beta>0$ for the regularisation strength, the mix-in replaces the anchor $p$ by the mixture $p_\gamma=(1-\gamma)p+\gamma d$, and the maximiser of $q\mapsto \E_q[r]-\beta\KL(q\|p_\gamma)$ is the Gibbs tilt $q^*_{\beta,\gamma}(y)\propto p_\gamma(y)e^{r(y)/\beta}$. Our main theorem is a \emph{two-scale drift law}: for all $\beta>0$ and all rewards with $L\le r\le M$,
\[
\Bigl|\;\|q^*_{\beta,\gamma}-p\|_1-\gamma\|d-p\|_1\;\Bigr|\;\le\; e^{(M-L)/\beta}\,\frac{\sigma_{p_\gamma}(r)}{\beta}.
\]
Hence $\|q^*_{\beta,\gamma}-p\|_1\to\gamma\|d-p\|_1$, so for $\gamma>0$ and $d\ne p$ the aligned policy never returns to the reference policy, however strong the regularisation. This \emph{alignment floor} is model independent: for any anchor $m$, $\|\tilt_\beta(m)-p\|_1\to\|m-p\|_1$, so the optimum returns to $p$ if and only if the anchor \emph{is} $p$; this covers the geometric mix-in $p^{1-\gamma}d^\gamma/Z$ as well as the arithmetic one. Dualising against the reward gives the floor in reward units: $\E_{q^*_{\beta,\gamma}}[r]\to\E_p[r]+\gamma(\E_d[r]-\E_p[r])$. We further show the $\sigma/\beta$ law is an upper bound only: the exact first-order constant is the mean absolute deviation, $\beta\|\tilt_\beta(m)-m\|_1\to\E_m|r-\E_m r|$, with sandwich $\sigma^2/(M-L)\le\MAD\le\sigma$. Finally, under a nondegeneracy condition the exact $1/\beta$ coefficient of the total drift is a \emph{signed} covariance $\sum_y\sgn(p_\gamma(y)-p(y))p_\gamma(y)(r(y)-\E_{p_\gamma}r)$, which may be negative: reward optimisation can partially cancel the pretraining tax.
\end{abstract}

\section{Introduction}

\subsection{The regularised alignment optimum}

Fix a finite output space $\Omega$. A \emph{policy} is a probability distribution on $\Omega$; a \emph{reward} is a function $r:\Omega\to\R$. The canonical alignment problem is
\begin{equation}\label{eq:base}
\max_q\;\E_q[r]-\beta\KL(q\|p),
\end{equation}
where $p$ is a fixed reference (supervised fine-tuned) policy and $\beta>0$ trades reward against deviation. Its unique maximiser is the exponential (Gibbs) tilt
\begin{equation}\label{eq:tilt}
\pi_\beta(y)=\frac{p(y)e^{r(y)/\beta}}{\sum_z p(z)e^{r(z)/\beta}}.
\end{equation}
Two structural facts make $\beta$ a natural safety dial. First, $\pi_\beta\to p$ as $\beta\to\infty$. Second, the approach is at rate $1/\beta$: in the $\ell^1$ (unnormalised total variation) norm $\|f-g\|_1=\sum_y|f(y)-g(y)|$ one has $\|\pi_\beta-p\|_1=\Theta(\sigma_p(r)/\beta)$.

\subsection{The pretraining mix-in}

Production alignment pipelines augment \eqref{eq:base} with a \emph{pretraining mix-in}: a fraction $\gamma$ of the training signal is drawn from the original pretraining distribution $d$, as a hedge against the capability degradation that reward optimisation induces. In the \emph{anchor formulation} studied here the mix-in replaces the reference measure of the KL penalty with the mixture
\begin{equation}\label{eq:mix}
p_\gamma:=(1-\gamma)p+\gamma d,
\end{equation}
so the objective becomes
\begin{equation}\label{eq:ptxobj}
\max_q\;\E_q[r]-\beta\KL(q\|p_\gamma),
\end{equation}
with optimum
\begin{equation}\label{eq:ptxopt}
q^*_{\beta,\gamma}(y)=\frac{p_\gamma(y)e^{r(y)/\beta}}{\sum_z p_\gamma(z)e^{r(z)/\beta}}.
\end{equation}
This paper determines what becomes of the two structural facts above under \eqref{eq:ptxobj}. The answer: the \emph{rate} survives, but the \emph{limit} does not. A $\beta$-independent residual displacement appears, of size exactly $\gamma\|d-p\|_1$.

\subsection{Contributions}

\begin{enumerate}
\item A two-scale drift law (Theorem~\ref{thm:twoscale}): a nonasymptotic two-sided estimate separating a $\beta$-independent mix-in term from a $\sigma/\beta$ reward term.
\item The alignment floor (Theorems~\ref{thm:floor}--\ref{thm:noreturn}).
\item Model independence (Theorem~\ref{thm:returniff}, Corollary~\ref{cor:geo}).
\item A Gibbs variational principle proving \eqref{eq:ptxopt} is the maximiser of \eqref{eq:ptxobj} (Theorem~\ref{thm:ptxoptimal}).
\item The floor in reward units (Theorem~\ref{thm:rewardtax}).
\item The sharp reward-drift constant, the mean absolute deviation, with the sandwich $\sigma^2/(M-L)\le\MAD\le\sigma$ (Theorems~\ref{thm:mad}, \ref{thm:sandwich}).
\item The exact $1/\beta$ correction to the floor: a signed covariance (Theorem~\ref{thm:ptxexp}).
\end{enumerate}

No differentiation of the free energy is used. The nonasymptotic estimates come from the convexity inequality $|e^a-e^b|\le e^{\max(a,b)}|a-b|$ combined with the variational characterisation of variance; the sharp constants come from the derivative of $t\mapsto e^{ct}$ at $t=0$ transported along $\beta\mapsto1/\beta$.

\section{Setting and definitions}

Throughout, $\Omega$ is a finite nonempty set and all sums range over $\Omega$.

\begin{definition}
A function $p:\Omega\to\R$ is a \emph{distribution} if $p(y)\ge0$ for all $y$ and $\sum_y p(y)=1$.
\end{definition}

\begin{definition}
For a distribution $p$ and $f:\Omega\to\R$,
\[
\E_p[f]=\sum_y p(y)f(y),\quad \Var_p(f)=\sum_y p(y)(f(y)-\E_p[f])^2,\quad \sigma_p(f)=\sqrt{\Var_p(f)},
\]
\[
\MAD_p(f)=\sum_y p(y)\bigl|f(y)-\E_p[f]\bigr|.
\]
\end{definition}

\begin{definition}
For $f,g:\Omega\to\R$, $\|f-g\|_1:=\sum_y|f(y)-g(y)|$, twice the total variation distance for distributions. It is symmetric, satisfies the triangle inequality, and vanishes exactly when $f=g$.
\end{definition}

\begin{definition}
For $\gamma\in\R$, $p_\gamma:=(1-\gamma)p+\gamma d$. For $\beta\ne0$, an anchor $m$ and reward $r$,
\[
Z_\beta(m,r):=\sum_z m(z)e^{r(z)/\beta},\qquad \tilt_\beta(m)(y):=\frac{m(y)e^{r(y)/\beta}}{Z_\beta(m,r)},
\]
and $q^*_{\beta,\gamma}:=\tilt_\beta(p_\gamma)$, i.e.\ exactly \eqref{eq:ptxopt}.
\end{definition}

\begin{definition}
$\KL(q\|s):=\sum_y q(y)\log(q(y)/s(y))$, with $0\log0=0$ built into the product form of the summand.
\end{definition}

\begin{lemma}\label{lem:mixdist}
If $p,d$ are distributions and $0\le\gamma\le1$, then $p_\gamma$ is a distribution and $\E_{p_\gamma}[f]=(1-\gamma)\E_p[f]+\gamma\E_d[f]$ for every $f$.
\end{lemma}
\begin{proof}
Nonnegativity is a nonnegative combination of nonnegative terms; the total mass is $(1-\gamma)+\gamma=1$. Linearity of the mean is immediate.
\end{proof}

\begin{lemma}\label{lem:tiltdist}
If $m$ is a distribution then $Z_\beta(m,r)>0$ and $\tilt_\beta(m)$ is a distribution; if $m>0$ pointwise then $\tilt_\beta(m)>0$ pointwise.
\end{lemma}
\begin{proof}
Since $\sum_y m(y)=1$, some $m(y)>0$; each summand of $Z_\beta$ is nonnegative and one is strictly positive. The tilt is nonnegative with total mass $Z_\beta/Z_\beta=1$.
\end{proof}

\begin{lemma}\label{lem:pointwise}
For a distribution $m$ and every $y$,
\begin{equation}\label{eq:ptw}
\tilt_\beta(m)(y)-m(y)=\frac{m(y)\bigl(e^{r(y)/\beta}-Z_\beta(m,r)\bigr)}{Z_\beta(m,r)},
\end{equation}
hence
\begin{equation}\label{eq:l1eq}
\|\tilt_\beta(m)-m\|_1=\frac{\sum_y m(y)\bigl|e^{r(y)/\beta}-Z_\beta(m,r)\bigr|}{Z_\beta(m,r)}.
\end{equation}
\end{lemma}
\begin{proof}
Algebra, then take absolute values using $Z_\beta>0$.
\end{proof}

Formula \eqref{eq:l1eq} is the engine of the paper: since $Z_\beta(m,r)=\E_m[e^{r/\beta}]$, the tilt's displacement is a mean absolute deviation of the exponentiated reward about its own mean.

\section{The two analytic inputs}

\begin{lemma}[Exponential Lipschitz estimate]\label{lem:explip}
For all $a,b\in\R$, $|e^a-e^b|\le e^{\max(a,b)}|a-b|$.
\end{lemma}
\begin{proof}
By symmetry assume $a\le b$. Then $|e^a-e^b|=e^b(1-e^{a-b})$ and $|a-b|=b-a$. Since $1+t\le e^t$ gives $1-e^t\le-t$ for $t\le0$, taking $t=a-b\le0$ yields $1-e^{a-b}\le b-a$.
\end{proof}

\begin{lemma}[Variational characterisation of variance]\label{lem:var}
For a distribution $p$, a function $f$ and any $c\in\R$, $\Var_p(f)\le\sum_y p(y)(f(y)-c)^2$.
\end{lemma}
\begin{proof}
$\sum_y p(y)(f(y)-c)^2=\Var_p(f)+(\E_p f-c)^2$.
\end{proof}

\begin{lemma}\label{lem:cs}
For a distribution $p$ and any $g$, $\sum_y p(y)|g(y)|\le\sqrt{\sum_y p(y)g(y)^2}$. In particular $\MAD_p(f)\le\sigma_p(f)$.
\end{lemma}
\begin{proof}
Cauchy--Schwarz with weights $\sqrt{p(y)}$, using $\sum_y p(y)=1$.
\end{proof}

We also use: if $L\le r\le M$ pointwise and $m$ is a distribution then $L\le\E_m[r]\le M$; and $Z_\beta(m,r)\ge e^{L/\beta}$ for $\beta>0$.

\section{The two-scale drift law}

\begin{theorem}[Exact anchor displacement]\label{thm:exactmix}
For any $p,d:\Omega\to\R$ and any $\gamma\ge0$, $\;\|p_\gamma-p\|_1=\gamma\|d-p\|_1$.
\end{theorem}
\begin{proof}
Pointwise $(1-\gamma)p(y)+\gamma d(y)-p(y)=\gamma(d(y)-p(y))$, so $|p_\gamma(y)-p(y)|=\gamma|d(y)-p(y)|$ using $\gamma\ge0$; sum over $y$.
\end{proof}

There is no error term: the mix-in displacement is a closed-form constant, independent of $\beta$ and $r$.

\begin{theorem}[Variance of the exponentiated reward]\label{thm:vartilt}
Let $m$ be a distribution, $\beta>0$, $r\le M$ pointwise. Then
\[
\Var_m\bigl(e^{r/\beta}\bigr)\le\Bigl(\tfrac{e^{M/\beta}}{\beta}\Bigr)^{2}\Var_m(r).
\]
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:var} with $c=e^{\E_m[r]/\beta}$. By Lemma~\ref{lem:explip}, each bracket $|e^{r(y)/\beta}-e^{\E_m[r]/\beta}|$ is at most $e^{\max(r(y),\E_m r)/\beta}|r(y)-\E_m r|/\beta\le(e^{M/\beta}/\beta)|r(y)-\E_m r|$, using $r\le M$ and $\E_m r\le M$. Square and sum.
\end{proof}

\begin{theorem}[Reward-drift bound: the $\sigma/\beta$ law]\label{thm:sigmabeta}
Let $m$ be a distribution, $\beta>0$, $L\le r\le M$ pointwise. Then
\[
\|\tilt_\beta(m)-m\|_1\le e^{(M-L)/\beta}\,\frac{\sigma_m(r)}{\beta}.
\]
\end{theorem}
\begin{proof}
Start from \eqref{eq:l1eq}. Since $Z_\beta(m,r)=\E_m[e^{r/\beta}]$, the numerator is $\MAD_m(e^{r/\beta})\le\sigma_m(e^{r/\beta})$ by Lemma~\ref{lem:cs}, which is at most $(e^{M/\beta}/\beta)\sigma_m(r)$ by Theorem~\ref{thm:vartilt}. The denominator is at least $e^{L/\beta}$, and $e^{M/\beta}/e^{L/\beta}=e^{(M-L)/\beta}$.
\end{proof}

\begin{theorem}[Two-scale drift law]\label{thm:twoscale}
Let $p,d$ be distributions, $0\le\gamma\le1$, $\beta>0$, $L\le r\le M$. Then
\[
\Bigl|\;\|q^*_{\beta,\gamma}-p\|_1-\gamma\|d-p\|_1\;\Bigr|\;\le\;e^{(M-L)/\beta}\,\frac{\sigma_{p_\gamma}(r)}{\beta}.
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:mixdist}, $p_\gamma$ is a distribution, so Theorem~\ref{thm:sigmabeta} bounds $\|q^*_{\beta,\gamma}-p_\gamma\|_1$ by the stated envelope $E_\beta$. The triangle inequality $\|q^*-p\|_1\le\|q^*-p_\gamma\|_1+\|p_\gamma-p\|_1$ with Theorem~\ref{thm:exactmix} gives the upper bound; the reverse form $\|p_\gamma-p\|_1\le\|p_\gamma-q^*\|_1+\|q^*-p\|_1$ with symmetry of $\|\cdot\|_1$ gives the lower bound.
\end{proof}

\begin{remark}
The estimate is nonasymptotic and holds for every $\beta>0$. Both scales are explicit: the constant scale $\gamma\|d-p\|_1$ and the vanishing scale $\sigma_{p_\gamma}(r)/\beta$ times a factor tending to $1$.
\end{remark}

\begin{theorem}[The alignment floor]\label{thm:floor}
Under the hypotheses of Theorem~\ref{thm:twoscale} with $L\le r\le M$ fixed,
\[
\lim_{\beta\to\infty}\|q^*_{\beta,\gamma}-p\|_1=\gamma\|d-p\|_1.
\]
\end{theorem}
\begin{proof}
$e^{(M-L)/\beta}\sigma_{p_\gamma}(r)/\beta\to1\cdot\sigma_{p_\gamma}(r)\cdot0=0$; apply Theorem~\ref{thm:twoscale}.
\end{proof}

\begin{theorem}[No return to the reference policy]\label{thm:noreturn}
If $0<\gamma\le1$ and $d\ne p$, then $\|q^*_{\beta,\gamma}-p\|_1\not\to0$ as $\beta\to\infty$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:floor} the limit exists and equals $\gamma\|d-p\|_1$. If it were $0$, uniqueness of limits forces $\gamma\|d-p\|_1=0$; since $\gamma>0$ this gives $\|d-p\|_1=0$, hence $d=p$, a contradiction.
\end{proof}

\section{The formula is a genuine optimum}

\begin{lemma}[Gibbs' inequality]\label{lem:gibbsineq}
If $q,s$ are distributions with $s>0$ pointwise, then $\KL(q\|s)\ge0$; moreover $\KL(s\|s)=0$.
\end{lemma}
\begin{proof}
We show $-q(y)\log(q(y)/s(y))\le s(y)-q(y)$ for each $y$. If $q(y)=0$ the left side is $0\le s(y)$. If $q(y)>0$, put $t=s(y)/q(y)>0$; then $\log t\le t-1$, so $q(y)\log t\le s(y)-q(y)$, and $q(y)\log t=-q(y)\log(q(y)/s(y))$. Summing gives $-\KL(q\|s)\le1-1=0$.
\end{proof}

\begin{lemma}[Free-energy identity]\label{lem:freeenergy}
Let $m$ be a strictly positive distribution, $\beta>0$, $q$ any distribution. Then
\begin{equation}\label{eq:fe}
\E_q[r]-\beta\KL(q\|m)=\beta\log Z_\beta(m,r)-\beta\KL\bigl(q\|\tilt_\beta(m)\bigr).
\end{equation}
\end{lemma}
\begin{proof}
With $g=\tilt_\beta(m)$ we have $\log(q(y)/g(y))=\log(q(y)/m(y))-r(y)/\beta+\log Z_\beta(m,r)$ whenever $q(y)>0$. Multiplying by $\beta q(y)$, summing and using $\sum_y q(y)=1$ gives $\beta\KL(q\|g)=\beta\KL(q\|m)-\E_q[r]+\beta\log Z_\beta(m,r)$, which rearranges to \eqref{eq:fe}.
\end{proof}

\begin{theorem}[Gibbs variational principle]\label{thm:gibbsopt}
Let $m$ be a strictly positive distribution and $\beta>0$. For every distribution $q$,
\[
\E_q[r]-\beta\KL(q\|m)\;\le\;\E_{\tilt_\beta(m)}[r]-\beta\KL(\tilt_\beta(m)\|m).
\]
\end{theorem}
\begin{proof}
Apply \eqref{eq:fe} to $q$ and to $g=\tilt_\beta(m)$. For $g$ the correction is $\beta\KL(g\|g)=0$, so the right side equals $\beta\log Z_\beta(m,r)$; for $q$ the correction is $\beta\KL(q\|g)\ge0$ by Lemma~\ref{lem:gibbsineq} (note $g>0$ by Lemma~\ref{lem:tiltdist}), so the left side is at most $\beta\log Z_\beta(m,r)$.
\end{proof}

\begin{theorem}[The PTX optimum]\label{thm:ptxoptimal}
Let $p,d$ be strictly positive distributions, $0\le\gamma\le1$, $\beta>0$. Then $p_\gamma>0$ pointwise and for every distribution $q$,
\[
\E_q[r]-\beta\KL(q\|p_\gamma)\le\E_{q^*_{\beta,\gamma}}[r]-\beta\KL(q^*_{\beta,\gamma}\|p_\gamma).
\]
\end{theorem}
\begin{proof}
If $\gamma=0$ then $p_\gamma=p>0$; if $\gamma>0$ then $p_\gamma(y)\ge\gamma d(y)>0$. Apply Theorem~\ref{thm:gibbsopt} with $m=p_\gamma$.
\end{proof}

\section{Model independence: the floor is the anchor displacement}

\begin{lemma}\label{lem:revtri}
For $f,g,h$, $\;\bigl|\|f-h\|_1-\|g-h\|_1\bigr|\le\|f-g\|_1$.
\end{lemma}

\begin{theorem}[Anchor limit]\label{thm:anchorlimit}
Let $m$ be a distribution, $L\le r\le M$, and $f$ any fixed function. Then $\|\tilt_\beta(m)-f\|_1\to\|m-f\|_1$ as $\beta\to\infty$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:revtri} and Theorem~\ref{thm:sigmabeta}, the difference is bounded by $\|\tilt_\beta(m)-m\|_1\le e^{(M-L)/\beta}\sigma_m(r)/\beta\to0$.
\end{proof}

\begin{theorem}[Return criterion]\label{thm:returniff}
For any distributions $m,p$ and any bounded reward,
\[
\lim_{\beta\to\infty}\|\tilt_\beta(m)-p\|_1=0\quad\Longleftrightarrow\quad m=p.
\]
\end{theorem}
\begin{proof}
($\Rightarrow$) By Theorem~\ref{thm:anchorlimit} the limit is $\|m-p\|_1$; uniqueness of limits gives $\|m-p\|_1=0$, hence $m=p$. ($\Leftarrow$) Substitute $m=p$.
\end{proof}

\begin{definition}[Geometric mix-in]
For strictly positive $p,d$ and $\gamma\in\R$,
\[
p^{\mathrm{geo}}_\gamma(y):=\frac{p(y)^{1-\gamma}d(y)^{\gamma}}{\sum_z p(z)^{1-\gamma}d(z)^{\gamma}},
\]
the anchor generated by regularising with $(1-\gamma)\KL(q\|p)+\gamma\KL(q\|d)$ rather than by mixing data. It is a distribution.
\end{definition}

\begin{corollary}[Robustness across mix-in models]\label{cor:geo}
$\lim_{\beta\to\infty}\|\tilt_\beta(p^{\mathrm{geo}}_\gamma)-p\|_1=0$ if and only if $p^{\mathrm{geo}}_\gamma=p$.
\end{corollary}
\begin{proof}
Theorem~\ref{thm:returniff} with $m=p^{\mathrm{geo}}_\gamma$.
\end{proof}

For $\gamma\in(0,1]$ the condition $p^{\mathrm{geo}}_\gamma=p$ forces $d=p$. The floor is a property of the anchor, not of the mixing rule.

\section{The floor in reward units}

\begin{lemma}[$\ell^1$--$\ell^\infty$ duality]\label{lem:duality}
If $|h|\le C$ pointwise then $|\E_f[h]-\E_g[h]|\le C\|f-g\|_1$.
\end{lemma}
\begin{proof}
$\E_f[h]-\E_g[h]=\sum_y(f(y)-g(y))h(y)$; bound termwise.
\end{proof}

\begin{theorem}\label{thm:anchormean}
Let $m$ be a distribution, $L\le r\le M$, $|r|\le C$. Then $\E_{\tilt_\beta(m)}[r]\to\E_m[r]$ as $\beta\to\infty$.
\end{theorem}
\begin{proof}
By Lemmas~\ref{lem:duality} and Theorem~\ref{thm:sigmabeta}, the difference is at most $C e^{(M-L)/\beta}\sigma_m(r)/\beta\to0$.
\end{proof}

\begin{theorem}[The reward-level alignment tax]\label{thm:rewardtax}
Let $p,d$ be distributions, $0\le\gamma\le1$, $L\le r\le M$, $|r|\le C$. Then
\[
\lim_{\beta\to\infty}\E_{q^*_{\beta,\gamma}}[r]=\E_p[r]+\gamma\bigl(\E_d[r]-\E_p[r]\bigr).
\]
\end{theorem}
\begin{proof}
Theorem~\ref{thm:anchormean} with $m=p_\gamma$ gives limit $\E_{p_\gamma}[r]$, which equals $(1-\gamma)\E_p[r]+\gamma\E_d[r]$ by Lemma~\ref{lem:mixdist}.
\end{proof}

\begin{remark}
The shift $\gamma(\E_d[r]-\E_p[r])$ is $\beta$-independent and negative precisely when the pretraining distribution is worse-rewarded than the reference policy --- the typical case. Both factors are estimable before training.
\end{remark}

\section{The sharp reward-drift constant}

\begin{lemma}\label{lem:rescexp}
For any $c\in\R$, $\beta(e^{c/\beta}-1)\to c$ as $\beta\to\infty$.
\end{lemma}
\begin{proof}
This is the derivative of $t\mapsto e^{ct}$ at $t=0$ along $t=1/\beta\downarrow0$.
\end{proof}

\begin{lemma}\label{lem:rescpart}
For a distribution $m$: $Z_\beta(m,r)\to1$ and $\beta(Z_\beta(m,r)-1)\to\E_m[r]$; hence $\beta(e^{r(y)/\beta}-Z_\beta(m,r))\to r(y)-\E_m[r]$ for each $y$.
\end{lemma}
\begin{proof}
$\beta(Z_\beta-1)=\sum_y m(y)\beta(e^{r(y)/\beta}-1)\to\sum_y m(y)r(y)$ by Lemma~\ref{lem:rescexp} termwise over a finite sum; $Z_\beta\to1$ since $e^{r(y)/\beta}\to1$ termwise.
\end{proof}

\begin{theorem}[Sharp drift constant]\label{thm:mad}
For every distribution $m$ and every $r$,
\[
\lim_{\beta\to\infty}\beta\,\|\tilt_\beta(m)-m\|_1=\MAD_m(r)=\E_m\bigl|r-\E_m r\bigr|.
\]
\end{theorem}
\begin{proof}
By \eqref{eq:l1eq}, $\beta\|\tilt_\beta(m)-m\|_1=\sum_y m(y)|\beta(e^{r(y)/\beta}-Z_\beta)|/Z_\beta$. Each numerator term converges to $m(y)|r(y)-\E_m r|$ by Lemma~\ref{lem:rescpart} and continuity of $|\cdot|$; the denominator converges to $1$. The sum is finite.
\end{proof}

\begin{theorem}[Reverse comparison]\label{thm:revcomp}
If $L\le r\le M$ then $\sigma_m(r)^2\le(M-L)\MAD_m(r)$.
\end{theorem}
\begin{proof}
Since $L\le r\le M$ and $L\le\E_m r\le M$, every deviation satisfies $|r(y)-\E_m r|\le M-L$, hence $(r(y)-\E_m r)^2\le(M-L)|r(y)-\E_m r|$. Weight by $m(y)$ and sum.
\end{proof}

\begin{theorem}[The sandwich]\label{thm:sandwich}
If $L\le r\le M$ with $L<M$, then $\;\sigma_m(r)^2/(M-L)\le\MAD_m(r)\le\sigma_m(r)$.
\end{theorem}
\begin{proof}
Right: Lemma~\ref{lem:cs}. Left: rearrange Theorem~\ref{thm:revcomp}.
\end{proof}

\begin{corollary}
Writing $\rho:=\sigma_m(r)/(M-L)\in[0,1]$, the drift satisfies $\rho\,\sigma_m(r)/\beta\lesssim\|\tilt_\beta(m)-m\|_1\lesssim\sigma_m(r)/\beta$ to first order. Thus the $\Theta(\sigma/\beta)$ law is two-sided exactly up to the dimensionless factor $\rho$ and cannot be sharpened to an equality; the honest constant is $\MAD$.
\end{corollary}

\begin{theorem}\label{thm:ptxmad}
For distributions $p,d$ and $0\le\gamma\le1$, $\;\beta\|q^*_{\beta,\gamma}-p_\gamma\|_1\to\MAD_{p_\gamma}(r)$.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:mad} with $m=p_\gamma$.
\end{proof}

\section{The exact $1/\beta$ correction is a signed covariance}

\begin{definition}
For $f,g:\Omega\to\R$ set $s_{f,g}(y):=+1$ if $g(y)<f(y)$ and $-1$ otherwise. Whenever $g(y)\ne f(y)$, $|f(y)-g(y)|=s_{f,g}(y)(f(y)-g(y))$.
\end{definition}

\begin{lemma}\label{lem:ptwlim}
For a distribution $m$ and each $y$: $\tilt_\beta(m)(y)\to m(y)$ and $\beta(\tilt_\beta(m)(y)-m(y))\to m(y)(r(y)-\E_m[r])$.
\end{lemma}
\begin{proof}
Both follow from \eqref{eq:ptw} and Lemma~\ref{lem:rescpart}.
\end{proof}

\begin{theorem}[Exact $1/\beta$ correction, general anchor]\label{thm:anchorexp}
Let $m$ be a distribution and $p$ a function with $p(y)\ne m(y)$ for every $y$. Then
\[
\lim_{\beta\to\infty}\beta\Bigl(\|\tilt_\beta(m)-p\|_1-\|m-p\|_1\Bigr)=\sum_y s_{m,p}(y)\,m(y)\bigl(r(y)-\E_m[r]\bigr).
\]
\end{theorem}
\begin{proof}
Fix $y$. Since $m(y)\ne p(y)$, either $p(y)<m(y)$, in which case $s_{m,p}(y)=1$ and by Lemma~\ref{lem:ptwlim} $\tilt_\beta(m)(y)>p(y)$ for all large $\beta$; or $p(y)>m(y)$, symmetrically with $s_{m,p}(y)=-1$. In both cases $|\tilt_\beta(m)(y)-p(y)|=s_{m,p}(y)(\tilt_\beta(m)(y)-p(y))$ eventually, and finiteness of $\Omega$ gives a single threshold valid for all $y$. For such $\beta$,
\[
\|\tilt_\beta(m)-p\|_1-\|m-p\|_1=\sum_y s_{m,p}(y)\bigl(\tilt_\beta(m)(y)-m(y)\bigr),
\]
the $p$ terms cancelling exactly. Multiply by $\beta$ and apply Lemma~\ref{lem:ptwlim} termwise.
\end{proof}

\begin{theorem}[PTX drift to first order]\label{thm:ptxexp}
Let $p,d$ be distributions, $0\le\gamma\le1$, and suppose $p(y)\ne p_\gamma(y)$ for every $y$. Then
\[
\|q^*_{\beta,\gamma}-p\|_1=\gamma\|d-p\|_1+\frac1\beta\sum_y\sgn\bigl(p_\gamma(y)-p(y)\bigr)p_\gamma(y)\bigl(r(y)-\E_{p_\gamma}[r]\bigr)+o(1/\beta).
\]
\end{theorem}
\begin{proof}
Theorem~\ref{thm:anchorexp} with $m=p_\gamma$, then substitute $\|p_\gamma-p\|_1=\gamma\|d-p\|_1$ (Theorem~\ref{thm:exactmix}).
\end{proof}

\begin{remark}
Contrast with Theorem~\ref{thm:ptxmad}, where the coefficient $\sum_y p_\gamma(y)|r(y)-\E_{p_\gamma}r|$ is nonnegative. Here the absolute value is replaced by a sign pattern determined by the anchor displacement, giving the covariance-type quantity $\E_{p_\gamma}[\sgn(p_\gamma-p)(r-\E_{p_\gamma}r)]$, which may be negative: if the reward is high precisely on outputs whose probability the mix-in reduced, then tilting toward the reward pushes those coordinates back toward $p$ and the total displacement decreases. Reward optimisation then partially cancels the pretraining tax --- though never below the floor $\gamma\|d-p\|_1$, which is the $\beta\to\infty$ limit itself.
\end{remark}

\begin{remark}
The nondegeneracy hypothesis is needed: at a coordinate where the anchor coincides with $p$ the sign of $q^*_{\beta,\gamma}(y)-p(y)$ is not eventually constant, and that coordinate contributes an absolute value, handled instead by the argument of Theorem~\ref{thm:mad}.
\end{remark}

\section{Algorithms}

On a finite output space of size $n$ the results yield three $O(n)$ procedures.

\paragraph{Exact PTX optimum.} Form $p_\gamma=(1-\gamma)p+\gamma d$; compute stabilised weights $w(y)=p_\gamma(y)\exp((r(y)-\max_z r(z))/\beta)$; normalise. The max-subtraction cancels in the normalisation and makes the computation stable for all $\beta>0$.

\paragraph{Drift certificate.} Compute $F=\gamma\|d-p\|_1$, $\sigma=\sigma_{p_\gamma}(r)$ and $E=e^{(M-L)/\beta}\sigma/\beta$; return the certified interval $[\max(0,F-E),F+E]$ containing $\|q^*_{\beta,\gamma}-p\|_1$, by Theorem~\ref{thm:twoscale}.

\paragraph{Asymptotic panel.} Return the floor $F$, the anchor-drift constant $\MAD_{p_\gamma}(r)$ with sandwich $[\sigma^2/(M-L),\sigma]$, the signed covariance coefficient of Theorem~\ref{thm:ptxexp}, and the reward tax $\gamma(\E_d[r]-\E_p[r])$. Together these predict the drift to $o(1/\beta)$ and the achieved reward to $o(1)$ with no optimisation performed.

\section{Applications and discussion}

The pair $(\beta,\gamma)$ is not two dials on the same axis: $\beta$ controls a perturbative $O(1/\beta)$ effect, $\gamma$ an $O(1)$ effect. Any argument of the form ``we set $\beta$ large, therefore the aligned model is close to the supervised model'' is invalid when $\gamma>0$; the correct statement is a lower bound $\|q^*-p\|_1\ge\gamma\|d-p\|_1-e^{(M-L)/\beta}\sigma_{p_\gamma}(r)/\beta$. Both the floor and the reward tax are computable before training. Using $\sigma$ rather than $\MAD$ as the drift constant systematically over-predicts by a factor between $1$ and $(M-L)/\sigma$. And by Theorem~\ref{thm:returniff} no reparametrisation of the mix-in escapes the floor: only a scheme leaving the anchor at $p$ --- e.g.\ a hard feasibility constraint rather than a shift of the reference measure --- changes the conclusion, and that is a different optimisation problem.

Three limitations. We model the mix-in as displacing the KL reference measure, the natural fixed-point idealisation of adding a pretraining likelihood term; Theorem~\ref{thm:returniff} shows insensitivity to the mixing rule, but the correspondence is a modelling assumption. The space $\Omega$ is finite so pointwise limits pass through sums; extension to infinite spaces requires uniform integrability of $e^{r/\beta}$, routine for bounded $r$. Finally we compare optima, not trajectories: real training reaches an approximate optimum, and quantifying that gap is open.

\section{Future directions}

\paragraph{Sharpening the expansion.} Conjecturally the error in Theorem~\ref{thm:ptxexp} is $O(\beta^{-2})$ with explicit constant, and the degenerate case admits a unified statement,
\[
\beta\Bigl(\|q^*_{\beta,\gamma}-p\|_1-\gamma\|d-p\|_1\Bigr)\to\!\!\sum_{y:\,p_\gamma(y)\ne p(y)}\!\!\sgn\bigl(p_\gamma(y)-p(y)\bigr)p_\gamma(y)\bigl(r(y)-\E_{p_\gamma}r\bigr)+\!\!\sum_{y:\,p_\gamma(y)=p(y)}\!\!p_\gamma(y)\bigl|r(y)-\E_{p_\gamma}r\bigr|,
\]
since the degenerate coordinates are exactly where the proof of Theorem~\ref{thm:mad} applies verbatim.

\paragraph{An unavoidable reward-unit tax.} Conjecturally, for $\gamma>0$ and $d\ne p$ there is $c(\gamma,d,p)>0$, independent of $\beta$, bounding the achieved reward away from the reward-optimal value uniformly over rewards of unit range.

\paragraph{Scheduled mix-ins.} Real pipelines vary $\gamma$ over training; the floor should be governed by the terminal anchor, but transient behaviour is open.

\paragraph{Other divergences.} The two-scale structure should persist in KL, Hellinger and Wasserstein distance, with the $O(1)$ term the corresponding anchor displacement and the $1/\beta$ constant the appropriate dispersion functional.

\section{Conclusion}

A pretraining mix-in of fraction $\gamma$ moves the reference measure of the KL-regularised alignment objective from $p$ to $p_\gamma=(1-\gamma)p+\gamma d$. Because the exponential tilt is an $O(1/\beta)$ perturbation of its anchor while the anchor shift is $O(1)$, the displacement of the optimum from the supervised policy splits as
\[
\|q^*_{\beta,\gamma}-p\|_1=\underbrace{\gamma\|d-p\|_1}_{\beta\text{-independent floor}}+\underbrace{O\bigl(\sigma_{p_\gamma}(r)/\beta\bigr)}_{\text{reward-induced}},
\]
with the floor exact, the envelope nonasymptotic, the floor independent of the mixing rule, the reward-unit version equal to $\gamma(\E_d[r]-\E_p[r])$, the sharp reward constant equal to the mean absolute deviation, and the exact $1/\beta$ coefficient of the total drift a signed covariance capable of partially cancelling the tax. The regularisation coefficient remains a dial for the reward-induced motion, and ceases to be one for the mix-in-induced motion.

